node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check all tables for references to PROD-2028EE
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('All tables:', tables.map(t => t.name));

// Check variants_json and any other variant table
const product = db.prepare(\"SELECT variants_json FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('variants_json:', product.variants_json);

// Check if there's a variants table or similar
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  const colNames = cols.map(c => c.name);
  if (colNames.some(c => c.includes('product') || c.includes('variant') || c.includes('item'))) {
    const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE product_id = ? OR 0', 'PROD-2028EE').all();
    if (rows.length > 0) {
      console.log(t.name + ':', JSON.stringify(rows, null, 2));
    }
  }
}
" 2>&1

